(()=>{const b=window.DriveQuizBank;if(!b)throw Error("Missing DriveQuizBank");b.questions.push(...[{"id":"rodrive-b-0801","batch":"17","category":"Categoria B","question":"Cum veți proceda la întâlnirea semnalului intermitent de culoare galbenă?","answers":["Acest semnal nu vă permite trecerea","Veți circula cu viteză redusă","Veți respecta semnificația semnalizării rutiere și a regulilor de circulație aplicabile în acel loc"],"correctIndices":[1,2],"correct":1,"explanation":"Atunci când întâlniți semnalul de culoare galbenă intermitent al semaforului electric, vă este permisă trecerea, însă aveți obligația să circulați cu viteză redusă și să respectați semnificația semnalizării rutiere sau a regulilor de circulație aplicabile în acel loc. De exemplu, în situația în care lângă semaforul pe culoarea galbenă intermitent este instalat indicatorul de reglementare de prioritate „Oprire”, veți circula cu viteză redusă și veți respecta semnificația indicatorului de reglementare de prioritate “Oprire”, oprind și acordând prioritate de trecere.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0801.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0801.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 801; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 800 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-veti-proceda-la-intalnirea-semnalului-intermitent-de-culoare-galbena","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"800","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0802","batch":"17","category":"Categoria B","question":"Ce obligații vă revin în timpul conducerii autovehiculului cu privire la viteză?","answers":["Să respectați viteza maximă admisă pe sectorul de drum pe care circulați, corespunzătoare categoriei din care face parte autovehiculul condus","Să vă conformați limitelor de viteză impuse prin mijloacele de semnalizare specifice","Să rulați pe cât posibil în treptele inferioare de viteză, pentru a nu polua mediul"],"correctIndices":[0,1],"correct":0,"explanation":"Conducătorii de vehicule sunt obligați să respecte viteza maximă admisă pe sectorul de drum pe care circulă și pentru categoria din care face parte vehiculul condus, precum și viteza maxima impusă prin mijloacele de semnalizare. De exemplu, dacă vă deplasați pe un drum din interiorul localității trebuie să circulați cu o viteză care să nu depășească limita maximă de viteză pentru drumurile din interiorul localităților, aceasta fiind de 50 de km/h. Însă dacă întâlniți un mijloc de semnalizare care impune o altă limită maximă de viteză, cum ar fi indicatorul „Limitare de viteză” la 40 de km/h, veți respecta limita impusă de respectivul indicator și veți circula cu o viteză care să nu depășească 40 km/h, pentru că semnificația indicatoarelor se va respecta cu prioritate față de regulile de circulație. Nu este obligatorie rularea, pe cât posibil, în treptele inferioare de viteză. Din contră, acest comportament al conducătorului de autovehicul duce la creșterea consumului de combustibil și implicit a poluării mediului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0802.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0802.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 802; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 801 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatii-va-revin-in-timpul-conducerii-autovehiculului-cu-privire-la-viteza","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"801","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0803","batch":"17","category":"Categoria B","question":"Întoarcerea unui vehicul este interzisă:","answers":["La o distanță mai mică de 50 m de stația de autobuz, troleibuz sau tramvai","În rampă, unde vizibilitatea este sub 50 m","Pe străzile pe care circulația se desfășoară în ambele sensuri"],"correctIndices":[1],"correct":1,"explanation":"Întoarcerea vehiculului este permisă la o distanță mai mică de 50 de metri de stațiile mijloacelor de transport public de persoane, această manevră fiind interzisă în stațiile mijloacelor de transport public și la mai puțin de 25 de metrii de acestea, deoarece în aceste locuri se interzice oprirea vehiculelor. Întoarcerea vehiculului este interzisă în apropierea vârfurilor de rampă, atunci când vizibilitatea este redusă sub 50 de metri. Pe drumurile pe care circulația se desfășoară în ambele sensuri, întoarcerea vehiculelor este permisă, cu condiția ca semnalizarea rutieră din respectivul loc să nu interzică această manevră.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0803.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0803.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 803; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 802 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/intoarcerea-unui-vehicul-este-interzisa","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"802","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0804","batch":"17","category":"Categoria B","question":"La ce distanță sunt instalate cele trei panouri suplimentare pentru avertizarea apropierii de o trecere la nivel cu calea ferată?","answers":["La 300, 200 și, respectiv, 100 m","La 90, 60 și, respectiv, 30 m","La 150, 100 și, respectiv, 50 m"],"correctIndices":[2],"correct":2,"explanation":"Trecerea la nivel cu calea ferată curentă este presemnalizată cu panouri suplimentare pentru avertizarea apropierii de o trecere la nivel cu o cale ferată, acestea sunt montate de o parte și de cealaltă a trecerii la nivel cu calea ferată, după cum urmează: La întâlnirea indicatorului cu trei linii, conducătorul auto este obligat să reducă viteza. La întâlnirea ultimului indicator, cel cu o singură linie, conducătorul auto nu mai are voie să execute nicio manevră (depășirea, oprirea, staționarea, mersul înapoi, întoarcerea). In oraș, din cauza condițiilor de trafic, sunt situații în care se găsește instalat numai cel de-al treilea panou, cel cu o singură linie.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0804.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0804.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 804; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 803 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/la-ce-distanta-sunt-instalate-cele-trei-panouri-suplimentare-pentru-avertizarea-apropierii-de-o-trecere-la-nivel-cu-calea-ferata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"803","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0805","batch":"17","category":"Categoria B","question":"Când nu este permis să măriți viteza de deplasare a vehiculului?","answers":["Când circulați pe prima bandă","Când un alt vehicul s-a angajat în depășirea dvs.","În intersecții"],"correctIndices":[1],"correct":1,"explanation":"Atunci când circulați pe prima bandă nu vă este interzis să măriți viteza de deplasare. Atunci când un alt vehicul s-a angajat în depășirea dvs. aveți obligația să nu măriți viteza de deplasare și să circulați cât mai aproape de marginea din dreapta a părții carosabile sau a benzii pe care vă deplasați. Atunci când circulați prin intersecții nu vă este interzis să măriți viteza de deplasare. Nu vi se poate interzice așa ceva, altfel nu ați mai putea pleca de pe loc în cazul în care ați fost oprit la semafor sau în cazul în care ați fost oprit pentru a acorda prioritate la intersecție.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0805.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0805.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 805; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 804 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cand-nu-este-permis-sa-mariti-viteza-de-deplasare-a-vehiculului","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"804","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0806","batch":"17","category":"Categoria B","question":"Conducătorul de vehicul care are mai puțin de un an de practică de conducere, va circula cu o viteză maximă admisă în afara localităților, mai mică cu:","answers":["10 km/h","20 km/h","25 km/h"],"correctIndices":[1],"correct":1,"explanation":"Viteza maximă admisă în afara localităților pentru autovehiculele ai căror conducători au mai puțin de un an practică de conducere estecu 20 km/h mai micădecât viteza maximă admisă pentru categoria din care face parte autovehiculul condus. De exemplu, viteza maximă admisă pentru conducătorul unui autovehicul din categoria B care are mai puțin de un an practică de conducere, atunci când circulă pe un drum național din afara localității, este de 90 - 20 = 70 km/h.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0806.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0806.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 806; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 805 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/conducatorul-de-vehicul-care-are-mai-putin-de-un-an-de-practica-de-conducere-va-circula-cu-o-viteza-maxima-admisa-in-afara-localitatilor-mai","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"805","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0807","batch":"17","category":"Categoria B","question":"Mersul înapoi este interzis:","answers":["La mai puțin de 100 m de trecerile la nivel cu calea ferată","La ieșirea din curți, garaje sau ganguri","Pe străzile unde circulația se desfășoară într-un singur sens"],"correctIndices":[1],"correct":1,"explanation":"Mersul înapoi cu vehicululNUeste interzis la mai puțin de100 metride trecerile la nivel cu calea ferată, dar este interzis pe trecerile la nivel cu calea ferată curentă și la o distanțămai mica de 50 metriînainte și după acestea. Legislația rutieră interzice mersul înapoi acolo unde se interzice întoarcerea -> întoarcerea este interzisă acolo unde este interzisă oprirea -> iar oprirea este interzisă pe trecerile la nivel cu calea ferată curentă și la o distanță mai mica de 50 de metri înainte și după acestea. Se interzice mersul înapoi cu vehiculul la ieșirea de pe proprietăți alăturate drumului public. Este interzis mersul înapoi în aceste situații deoarece vizibilitatea este foarte scăzută. La ieșirea de pe proprietățile alăturate drumului public, vehiculele se scot cu fața și se acordă prioritate de trecere tuturor participanților la trafic, indiferent din ce direcție circulă aceștia. Pe străzile unde circulația se desfășoarăîntr-un singur sens(sens unic), mersul înapoi cu vehiculul este permis, însă se poate efectua pe o distanță demaxim 50 de metri. Pe orice tip sau categorie de drum circulați, dacă mersul înapoi cu vehiculul este permis, tot pe o distanță de maxim 50 de metri puteți manevra vehiculul înapoi.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0807.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0807.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 807; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 806 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/mersul-inapoi-este-interzis","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"806","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0808","batch":"17","category":"Categoria B","question":"Ce obligații aveți când sesizați că urmează să fiți depășit de un alt autovehicul?","answers":["Să reduceți viteza de mers","Să nu măriți viteza de mers","Să circulați cât mai aproape de marginea din dreapta a carosabilului sau a benzii pe care vă deplasați"],"correctIndices":[1,2],"correct":1,"explanation":"Legislația rutieră nu vă obligă la reducerea vitezei de deplasare în cazul în care sunteți depășit de un alt autovehicul. Nu există un articol de lege care să vă oblige la așa ceva. Trebuie să nu confundați cu situația în care pe timp de noapte, la apropierea de un alt vehicul care circulă din sens opus, aveți obligația de a reduce viteza de deplasare și de a folosi luminile de întâlnire. Atunci când sesizați că urmează să fiți depășit de un alt autovehicul, aveți obligația de a nu mări viteza de deplasare și de a circula cât mai aproape de marginea din dreapta a părții carosabile sau a benzii pe care vă deplasați.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0808.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0808.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 808; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 807 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatii-aveti-cand-sesizati-ca-urmeaza-sa-fiti-depasit-de-un-alt-autovehicul","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"807","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0809","batch":"17","category":"Categoria B","question":"În care dintre situații este interzisă oprirea?","answers":["La o distanță mai mică de 25 m înainte și după indicatorul de stație pentru mijloacele de transport public de persoane","La o distanță mai mică de 25 m de colțul intersecției","La o distanță de 5 m în spatele ultimului vagon de tramvai oprit într-o stație fără refugiu pentru pietoni"],"correctIndices":[0,1],"correct":0,"explanation":"Regulamentul rutier interzice oprirea voluntară a vehiculelor în stațiile mijloacelor de transport public de persoane, precum și la mai puțin de 25 m înainte și după acestea. Regulamentul rutier interzice oprirea voluntară a vehiculelor în intersecții, inclusiv cele cu circulație în sens giratoriu, precum și în zona de preselecție unde sunt aplicate marcaje continue, iar în lipsa acestora, la o distanță mai mica de 25 m de coltul intersecției. Legislația rutieră nu interzice oprirea la o distanță de 5 metri în spatele ultimului vagon de tramvai oprit într-o stație fără refugiu pentru pietoni, nu există un articol în legislație care să specifice acest lucru. Dar trebuie sa ținem cont că oprirea este interzisa în stațiile mijloacelor de transport public de persoane, precum și la mai puțin de 25 m înainte și după acestea. Legislația specifică și faptul că atunci când întâlniți un tramvai oprit într-o stație fără refugiu pentru pietoni, sunteți obligat să opriți în spatele tramvaiului, și vă puteți relua deplasarea numai după ce ușile tramvaiului au fost închise și v-ați asigurat că nu puneți în pericol siguranța pietonilor angajați în traversarea drumului public.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0809.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0809.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 809; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 808 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-care-dintre-situatii-este-interzisa-oprirea","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"808","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0810","batch":"17","category":"Categoria B","question":"Conducând pe drumul public, vă faceți mai vizibil autoturismul dacă:","answers":["Îl împodobiți cu abțibilduri sau accesorii colorate, fixate pe parbriz și pe lunetă","Vopsiți în culoarea albă sau galbenă partea din față și din spate a caroseriei","Asigurați curățenia exteriorului caroseriei, a tăblițelor cu numărul de înmatriculare, precum și a sistemelor de iluminare-semnalizare"],"correctIndices":[2],"correct":2,"explanation":"Nu se recomandă să vă împodobiți autoturismul cu abțibilduri sau accesorii colorate, fixate pe parbriz și pe lunetă, pentru al face mai vizibil pe drumul public. Trebuie să țineți cont că vă este interzis să aplicați pe luneta sau pe geamurile laterale afișe, reclame publicitare, înscrisuri ori accesorii, care restrâng sau estompează vizibilitatea. Nu se recomandă să vă vopsiți în culoarea albă sau galbenă partea din față și din spate a caroseriei, pentru al face mai vizibil pe drumul public. Atunci când conduceți pe drumul public, vă faceți mai vizibil autoturismul dacă asigurați curățenia exteriorului caroseriei, a tăblițelor cu numărul de înmatriculare, precum și a sistemelor de iluminare-semnalizare. Aceasta este și o obligație prevăzută de legislația rutieră.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0810.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0810.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 810; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 809 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/conducand-pe-drumul-public-va-faceti-mai-vizibil-autoturismul-daca","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"809","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0811","batch":"17","category":"Categoria B","question":"Factorii principali care ajută un conducător auto să piloteze preventiv sunt:","answers":["Atitudinea pozitivă în trafic, calmul, cunoștințele dobândite și politețea","Iscusința și priceperea de a-și impune calitățile fizice dobândite","Mijloacele de semnalizare rutieră și agenții de poliție rutieră"],"correctIndices":[0],"correct":0,"explanation":"În întrebare este vorba desprefactorii principali, adică factorii cei mai prezenți, cei care constituie baza în conducerea preventivă. Prin urmare, atitudinea pozitivă în trafic, calmul, cunoștințele dobândite și politețea sunt factorii principali care ajută un conducător auto să piloteze preventiv. Iscusința și priceperea de a-și impune calitățile fizice dobânditeNUsunt factori principali ai conduitei preventive. Mijloacele de semnalizare rutieră și agenții de poliție rutierăNUsunt factori principali ai conduitei preventive. Prin urmare, dintre cele trei variante de răspuns cea care reprezintă baza conduitei preventive este: „atitudinea pozitivă în trafic, calmul, cunoștințele dobândite și politețea”. Conducerea preventivă (conduita preventivă) - reprezintă comportamentul conducătorului auto caracterizat prin următoarele trăsături esențiale: În concluzie, prin conduită preventivă se înțelege comportamentul rutier care asigură prevenirea accidentelor, prin anticiparea și evitarea acțiunilor incorecte ale partenerilor de drum, precum și adaptarea vitezei de deplasare la condițiile meteo-rutiere specifice. Conduita preventivă asigură siguranța și fluența deplasării pe drumurile publice. Elementele conducerii preventive:","imageUrl":"/nivel-1/quiz-images/rodrive-all/0811.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0811.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 811; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 810 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/factorii-principali-care-ajuta-un-conducator-auto-sa-piloteze-preventiv-sunt","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"810","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0812","batch":"17","category":"Categoria B","question":"Precizați când sunt scutiți instructorii auto de purtarea centurii de siguranță:","answers":["În timpul orelor de pregătire a cursanților","În permanență, când se află în autovehiculele cu inscripția „şcoala“","Legal, nu este prevăzut"],"correctIndices":[0],"correct":0,"explanation":"Instructorul auto, pe timpul pregătirii practice a persoanelor care învață să conducă un autovehicul pe drumurile publice, este exceptat de la obligația de a purta centura de siguranță.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0812.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0812.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 812; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 811 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/precizati-cand-sunt-scutiti-instructorii-auto-de-purtarea-centurii-de-siguranta","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"811","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0813","batch":"17","category":"Categoria B","question":"Vi se interzice circulația cu autoturismul pe drumurile publice când:","answers":["Zgomotul în mers sau în staționare depășește limita legală admisă","Oglinzile retrovizoare sunt de dimensiuni mai mari","Dispozitivul de avertizare sonoră nu este corespunzător"],"correctIndices":[0],"correct":0,"explanation":"Se interzice circulația cu autoturismul pe drumurile publice când zgomotul în mers sau în staționare depășește limita legală admisă. Pentru această faptă se reține certificatul de înmatriculare sau de înregistrare. NUse interzice circulația cu autoturismul pe drumurile publice când oglinzile retrovizoare sunt de dimensiuni mai mari, legislația rutieră nu prevede o astfel de interzicere. NUse interzice circulația cu autoturismul pe drumurile publice când dispozitivul de avertizare sonoră nu este corespunzător.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0813.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0813.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 813; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 812 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/vi-se-interzice-circulatia-cu-autoturismul-pe-drumurile-publice-cand","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"812","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0814","batch":"17","category":"Categoria B","question":"În funcție de starea accidentatului, măsurile de prim ajutor se vor lua în următoarea ordine:","answers":["Oprirea hemoragiei, pansarea rănilor, imobilizarea fracturilor, respirația artificială, masajul cardiac","Respirația artificială, masajul cardiac, oprirea hemoragiei, pansarea rănilor, imobilizarea fracturilor","Imobilizarea fracturilor, pansarea rănilor, respirația artificială, masajul cardiac, oprirea hemoragiei"],"correctIndices":[1],"correct":1,"explanation":"Este importantă cunoașterea ordinii în care luăm măsurile de acordare a primului ajutor, astfel încât persoanele care au nevoie de ajutor să aibă mai multe șanse de recuperare sau de supraviețuire. În funcție de starea accidentatului, măsurile de prim ajutor se vor lua în următoarea ordine:","imageUrl":"/nivel-1/quiz-images/rodrive-all/0814.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0814.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 814; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 813 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-functie-de-starea-accidentatului-masurile-de-prim-ajutor-se-vor-lua-in-urmatoarea-ordine","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"813","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0815","batch":"17","category":"Categoria B","question":"La apariția defecțiunilor tehnice ale mecanismului de direcție se procedează astfel:","answers":["Se apelează la cunoștințe care au mai întâlnit astfel de situații","Se continuă deplasarea, întrucât defecțiunea se datorează stării drumului public","Se apelează numai la atelierele specializate, care au personal calificat"],"correctIndices":[2],"correct":2,"explanation":"În cazul în care apelați la cunoștințe care au mai întâlnit astfel de situații, acestea or să vă sfătuiască să mergeți la atelierele specializate, care au personal calificat în astfel de defecțiuni. Conducerea vehiculului cu defecțiuni grave la mecanismul de direcție, constatate de poliția rutieră împreună cu specialiștii Registrului Auto Roman (RAR), constituie contravenție și se sancționează cu amendă prevăzută în clasa a IV-a, cu suspendarea permisului pentru 90 de zile, se reține certificatul de înmatriculare și se eliberează o dovadă fără drept de circulație, adică se imobilizează vehiculul. La apariția defecțiunilor tehnice ale mecanismului de direcție se apelează de urgență, numai la atelierele specializate, care au personal calificat. Mecanismul de direcție defect sau reparat necorespunzător poate pune în pericol siguranța circulației rutiere. Dacă defecțiunile mecanismului de direcție sunt grave, nu se va mai încerca conducerea acestuia și trebuie să apelați la o platformă care să vă transporte autovehiculul la o unitate specializată.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0815.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0815.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 815; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 814 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/la-aparitia-defectiunilor-tehnice-ale-mecanismului-de-directie-se-procedeaza-astfel","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"814","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0816","batch":"17","category":"Categoria B","question":"Ce obligații aveți la întâlnirea indicatorului?","answers":["Să circulați cu atenție mărită, pentru a evita pericolele asupra cărora sunteți avertizat","Să circulați cu viteză redusă, deoarece urmează o intersecție periculoasă","Să circulați cu lanțuri antiderapante, în condiții meteo nefavorabile"],"correctIndices":[0],"correct":0,"explanation":"Indicatorul din imagine se numește \"Alte pericole\", acesta vă avertizează despre existența unui pericol și se instalează în orice situație periculoasă pentru care nu este prevăzut un indicator de avertizare specific. Panoul adițional de sub acesta specifică tipul de pericol ce urmează, pericolul fiind de avalanșă. La întâlnirea acestui indicator se recomandă sporirea atenției pentru a evita pericolele asupra cărora sunteți avertizat. Acest indicator se găsește instalat și la trecerea la nivel cu o cale ferată industrială, însoțit de unpanou adiţionalce conține imaginea unei locomotive.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0816.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0816.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 816; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Indicatorul triunghiular cu margine roșie și un semn de exclamare negru, ce evidențiază prezența unui pericol, însoșit de inscripția 'Pericol de avalanșă' avertizează șoferul asupra riscului de avalanșe în zonă. Este amplasat pe drumuri montane unde condițiile meteorologice pot genera astfel de pericole.","needsImageReview":true,"source":"RoDrive · ID 815 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatii-aveti-la-intalnirea-indicatorului","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"815","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_840.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0817","batch":"17","category":"Categoria B","question":"Cum trebuie să procedați în acest caz?","answers":["Accelerați, pentru a trece prin fața pietonilor","Dați un semnal scurt de avertizare, pentru ca pietonii să nu se angajeze în traversare","Opriți, pentru a permite pietonilor traversarea"],"correctIndices":[2],"correct":2,"explanation":"Conducătorul de vehicul este obligat să acorde prioritate de trecere pietonului care traversează drumul public, prin loc special amenajat, marcat și semnalizat corespunzător, ori la culoarea verde a semaforului destinat lui, atunci când acesta se află pe sensul de mers al vehiculului. Prin urmare, în situația dată, pietonii aflându-se în traversare pe sensul dumneavoastră de mers, trebuie să opriți și să le acordați prioritate de trecere.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0817.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0817.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 817; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o trecere de pietoni semnalizată corespunzător, cu mai mulți pietoni care intenționează să traverseze strada.","needsImageReview":true,"source":"RoDrive · ID 816 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-trebuie-sa-procedati-in-acest-caz","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"816","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_841.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0818","batch":"17","category":"Categoria B","question":"Cum procedați în situația dată?","answers":["Frânați din timp, pentru a acorda prioritate de trecere pietonilor","Traversați strada accelerat","Traversați marcajul pentru pietoni înaintea acestora"],"correctIndices":[0],"correct":0,"explanation":"Conducătorul de vehicul este obligat să acorde prioritate de trecere pietonului care traversează drumul public, prin loc special amenajat, marcat și semnalizat corespunzător, ori la culoarea verde a semaforului destinat lui, atunci când acesta se află pe sensul de mers al vehiculului. Prin urmare, în situația dată, pietonii aflându-se în traversare pe sensul dumneavoastră de mers, trebuie să opriți și să le acordați prioritate de trecere.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0818.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0818.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 818; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o trecere de pietoni semnalizată prin indicatorul 'Trecere pentru pietoni'. Doi pietoni traversează strada.","needsImageReview":true,"source":"RoDrive · ID 817 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-procedati-in-situatia-data","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"817","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_842.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0819","batch":"17","category":"Categoria B","question":"Cine are prioritate pe sectorul de drum îngustat?","answers":["Autoturismul, deoarece circulă în dreapta autobuzului","Autobuzul, deoarece nu-și schimbă poziția de mers","Autoturismul, deoarece are o viteză de deplasare mai mare"],"correctIndices":[1],"correct":1,"explanation":"Pe drumul public cu mai multe benzi pe sens, conducătorii de autovehicule care circulă pe o bandă care se sfârșește, pentru a continua deplasarea pe banda din stânga, trebuie să permită trecerea (acorde prioritate) vehiculelor care circulă pe acea bandă. În situația din imagine, autovehiculul albastru trebuie să îi acorde prioritate autobuzului, după care se poate angaja pe banda din stânga, autobuzul având prioritate de trecere.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0819.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0819.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 819; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Această imagine ilustrează o intersecție în care vehiculul albastru vrea să se incadreze pe banda din stânga lui, deoarece a întâmpinat indicatorul triunghiular 'Drum îngustat'. La stânga lui este un autobuz care merge înainte. Autoturismul albastru este pe drumul îngustat.","needsImageReview":true,"source":"RoDrive · ID 818 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cine-are-prioritate-pe-sectorul-de-drum-ingustat","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"818","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_843.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0820","batch":"17","category":"Categoria B","question":"Semnalul verde al semaforului permite deplasarea:","answers":["Pe oricare direcție, dacă printr-un mijloc de semnalizare nu se dispune altfel","Numai pe direcția înainte","Pe oricare direcție, dacă vehiculul se află pe banda din mijloc"],"correctIndices":[0],"correct":0,"explanation":"Semnalul de culoare verde al semaforului permite trecerea, la întâlnirea semnalului verde, conducătorul de vehicul poate circula pe orice direcție dorește, dacă printr-un mijloc de semnalizare nu se dispune altfel. Un exemplu de situație în care se dispune altfel este situația în care conducătorul de autovehicul întâlnește semnalul verde dar și indicatorul de obligare „Înainte sau la dreapta” sau marcajul de obligare „Înainte sau la dreapta”, mijloace de semnalizare care îl obligă să circule doar pe direcțiile înainte sau la dreapta atunci când semnalul verde al semaforului îi permite trecerea. Virajul către stânga îi este interzis chiar dacă semaforul este pe culoarea verde. Un alt exemplu este situația în care sub semafoare se găsescpanouri adiționale sub forma unor săgeți, care indică direcțiile pentru care sunt valabile semnalele semafoarelor, iar conducătorul de autovehicul poate vira doar către direcția indicată de săgeata atașată la culoarea verde a semaforului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0820.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0820.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 820; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 819 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/semnalul-verde-al-semaforului-permite-deplasarea","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"819","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0821","batch":"17","category":"Categoria B","question":"În care dintre situațiile de mai jos este interzisă oprirea vehiculelor pe drumurile publice?","answers":["În intersecțiile cu sens giratoriu","În zona de acțiune a indicatorului „staționarea interzisă“","Pe arterele cu un singur sens de circulație"],"correctIndices":[0],"correct":0,"explanation":"Se interzice oprirea voluntară a vehiculelor în intersecții, inclusiv în cele cu circulație în sens giratoriu, precum și în zona de preselecție unde sunt aplicate marcaje continue, iar în lipsa acestora, la o distanță mai mică de 25 metri de colțul intersecției. În zona de acțiune a indicatorului „Staționarea interzisă”, se interzice staționarea vehiculelor, oprirea fiind permisă. Pe arterele cu un singur sens de circulație, adică pe cele cu sens unic, oprirea este permisă. Este permisă chiar și pe partea stângă a drumului dacă rămâne liberă cel puțin o bandă de circulație.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0821.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0821.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 821; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 820 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-care-dintre-situatiile-de-mai-jos-este-interzisa-oprirea-vehiculelor-pe-drumurile-publice","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"820","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0822","batch":"17","category":"Categoria B","question":"Care dintre participanții la traficul rutier au obligația de a respecta regulile de circulație pe drumurile publice din interiorul localităților?","answers":["Toți participanții la traficul rutier, indiferent de situație","Conducătorii auto, atât cei amatori, cât și cei profesioniști, atât ziua, cât și noaptea","Conducătorii autovehiculelor destinate transportului în comun, având în vedere destinația autovehiculelor pe care le conduc"],"correctIndices":[0],"correct":0,"explanation":"Toți participanții la traficul rutier, indiferent dacă sunt pietoni sau conducători de vehicule ori autovehicule, au obligația de a respecta regulile de circulație pe drumurile publice, atât în localități cât și în afara acestora, indiferent de situație.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0822.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0822.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 822; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 821 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-dintre-participantii-la-traficul-rutier-au-obligatia-de-a-respecta-regulile-de-circulatie-pe-drumurile-publice-din-interiorul-localitat","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"821","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0823","batch":"17","category":"Categoria B","question":"Ați accidentat un pieton care traversa strada neregulamentar. Ce obligații legale vă revin?","answers":["Anunțați imediat poliția, nu modificați sau ștergeți urmele accidentului și rămâneți pe loc","Vă prezentați de urgență la cea mai apropiată unitate de poliție","Deoarece vinovăția nu vă aparține, puteți continua drumul dacă accidentul nu este grav"],"correctIndices":[0],"correct":0,"explanation":"Dacă ați accidentat un pieton ce a traversat strada, indiferent dacă pietonul traversa regulamentar sau nu, aveți obligațiade a anunța poliția,de a nu modifica urmele accidentuluișide a nu părăsi locul faptei. În acest caz vă este interzis să părăsiți locul faptei fără încuviințarea poliției sau a procurorului care efectuează cercetarea. Nerespectarea interdicției de a părăsi locul fapteieste considerată infracțiuneși se pedepsește cuînchisoarea de la 2 la 7 ani. Cu toate acestea,NUconstituie infracțiunesituația în care,în lipsa altor mijloace de transport, conducătorul vehiculului implicat în accident transportă el însuși persoana rănită la cel mai apropiat spital,acesta având obligațiade a declara datele personale de identitate și numărul de înmatriculare sau înregistrare a vehiculului condus, date ce se vor consemna într-un registru special, și de a se reîntoarce imediat la locul accidentului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0823.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0823.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 823; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 822 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ati-accidentat-un-pieton-care-traversa-strada-neregulamentar-ce-obligatii-legale-va-revin","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"822","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0824","batch":"17","category":"Categoria B","question":"În care dintre următoarele situații se anulează permisul de conducere?","answers":["În urma unei condamnări, printr-o hotărâre definitivă, pentru o infracțiune la regimul circulației","Pentru încălcarea dispozițiilor legale referitoare la folosirea luminilor de întâlnire pe timp de noapte, în afara localităților","Pentru încălcarea dispozițiilor legale referitoare la obligația de a semnaliza schimbarea direcției de mers"],"correctIndices":[0],"correct":0,"explanation":"Permisul de conducere eliberat de autoritatea română se anulează dacă titularul acestuiaa fost condamnat printr-o hotărâre judecătorească rămasă definitivă, pentru o infracțiune la regimul circulației. Încălcarea dispozițiilor legale referitoare la folosirea luminilor de întâlnire pe timp de noapte, în afara localităților NU se sancționează cu anularea permisului de conducere. Pentru această faptă se aplică puncte de penalizare și amendă, în funcție de norma încălcată referitoare la folosirea luminilor pe timp de noapte. Încălcarea încălcarea dispozițiilor legale referitoare la obligația de a semnaliza schimbarea direcției de mers NU se sancționează cu anularea permisului de conducere. Pentru această faptă se aplică amenda contravențională prevăzută în clasa I de sancțiuni.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0824.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0824.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 824; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 823 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-care-dintre-urmatoarele-situatii-se-anuleaza-permisul-de-conducere","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"823","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0825","batch":"17","category":"Categoria B","question":"Permisul de conducere categoria B este valabil și pentru conducerea unui autovehicul destinat transportului de persoane, având mai mult de 8 locuri pe scaune, în afara locului conducătorului?","answers":["Da, dacă posesorul permisului are o vechime în conducere de cel puțin 1 an","Nu","Da, dacă conducătorul posedă și categoria be a permisului de conducere"],"correctIndices":[1],"correct":1,"explanation":"Permisul de conducere pentru categoria B permite conducerea unui autovehicul a cărui masă totală maximă autorizată nu depășește 3.500 kg și al cărui număr de locuri pe scaune, în afara conducătorului, nu este mai mare de 8.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0825.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0825.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 825; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 824 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/permisul-de-conducere-categoria-b-este-valabil-si-pentru-conducerea-unui-autovehicul-destinat-transportului-de-persoane-avand-mai-mult-de-8-","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"824","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0826","batch":"17","category":"Categoria B","question":"Ce trebuie să aveți în vedere la scoaterea persoanelor accidentate din autovehicul?","answers":["Ca operațiunea să se desfășoare rapid și fără să provoace alte traumatisme","Să nu se agraveze leziunile","Să nu se îndepărteze indiciile care ar putea ajuta la explicarea modului în care s-a produs accidentul"],"correctIndices":[1],"correct":1,"explanation":"Operațiunea de scoatere a persoanelor accidentate din autovehicul trebuie să se facă în așa fel încât să nu agraveze leziunile existente. În unele cazuri, dacă aceste proceduri se efectuează rapid, crește riscul de agravare a leziunilor existente sau de provocare a altor traumatisme. În cazul unui accident soldat cu persoane rănite în interiorul autovehiculului, la scoaterea acestora din autovehicul, trebuie să aveți în vedere să nu se agraveze leziunile. Dacă victimele nu sunt blocate, acestea vor fi scoase din autovehicul prin ridicare, în cazul în care victimele sunt blocate de parți ale autovehiculului, acestea se vor lăsa în mașină, fără a fi mișcate până la venirea echipajelor de descarcerare. Este interzisă îndepărtarea indiciilor care ar putea ajuta la explicarea modului în care s-a produs accidentul, dar dacă salvarea victimelor o impune, puteți îndepărta aceste indicii, dar la sosirea agenților care cercetează cazul le veți declara acestora ce anume a fost îndepărtat.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0826.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0826.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 826; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 825 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-trebuie-sa-aveti-in-vedere-la-scoaterea-persoanelor-accidentate-din-autovehicul","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"825","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0827","batch":"17","category":"Categoria B","question":"Uzura prematură a pneurilor din față se datorează, în primul rând:","answers":["Dereglării geometriei direcției","Circulației frecvente cu viteză redusă","Fenomenul este specific autovehiculelor care au tracțiunea pe puntea din spate"],"correctIndices":[0],"correct":0,"explanation":"Uzura prematură a pneurilor din față se datorează,în primul rând, dereglării geometriei direcției. Pentru un număr cât mai mare de kilometri parcurși, roțile trebuie echilibrate periodic și, în plus, efectuată permutarea roților (la aproximativ 10 000 - 20 000 km). Se mută roțile din spate în față și invers. De asemenea, periodic se verifică obligatoriu presiunea în pneuri (cel puțin lunar), la rece. Dacă presiunea este prea mare, pneul se uzează pe creasta benzii de rulare. Dacă presiunea este prea mică, pneul se uzează pe margini (în zona talonului), se încălzește, se pot desface firele de cord, astfel pneul devine inutilizabil și trebuie înlocuit. Uzura locală sau neuniformă a unui pneu se produce la supraîncărcarea autovehiculului sau când tamburul de frână se ovalizează ori roțile sunt neechilibrate. Uzura pe una din margini are loc datorită dereglării geometriei roților. Încălzirea excesivă a pneurilor se produce la presiuni foarte mici sau la suprasarcină. Circulația frecventă cu viteză redusă nu duce la uzura prematură a pneurilor. Autovehiculele cu tracțiunea pe puntea spate (mai exact cu propulsie pe puntea spate, deoarece roțile din spate împing autovehiculul, nu îl trag) vor toci mai greu pneurile de pe puntea față, datorită forței de propulsie care creează stres doar pe pneurile spate, nu și pe cele din față, dar nici acestea nu vor uza prematur pneurile, atât timp cât geometria este bine reglată și presiunea din pneuri este corectă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0827.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0827.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 827; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 826 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/uzura-prematura-a-pneurilor-din-fata-se-datoreaza-in-primul-rand","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"826","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0828","batch":"17","category":"Categoria B","question":"Indicatorul semnifică:","answers":["O trecere la nivel cu calea ferată","O trecere la nivel cu calea ferată industrială","Apropierea de un depou de tramvaie"],"correctIndices":[1],"correct":1,"explanation":"Indicatorul „Alte pericole” împreună cupanoul adiționalinstalat sub acesta vă avertizează că urmează o trecere la nivel cu o cale ferată industrială. Având în vedere că urmează o trecere la nivel cu o cale ferată industrială, aveți obligația să dați dovadă de prudență sporită și să vă conformați semnificației semnalelor agentului de cale ferată, fiind recomandat să se circule cu viteză redusă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0828.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0828.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 828; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un indicator triunghiular cu margine roșie și un semn de exclamare, însoțit de un panou adițional ce are simbolul unui tren industrial.","needsImageReview":true,"source":"RoDrive · ID 827 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/indicatorul-semnifica","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"827","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_853.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0829","batch":"17","category":"Categoria B","question":"Ce obligații revin conducătorilor la întâlnirea indicatorului?","answers":["Să acorde prioritate vehiculelor care circulă în intersecție","Să ocolească centrul intersecției și să circule cât mai aproape de marginea străzii","Să acorde prioritate de dreapta"],"correctIndices":[0],"correct":0,"explanation":"Indicatorul se numește “Intersecție cu sens giratoriu”, la întâlnirea acestuia conducătorii de vehicule au obligația de a acorda prioritate de trecere vehiculelor care circulă în interiorul acesteia. Circulația în astfel de intersecții se desfășoară ocolind centrul intersecției în senul indicat de săgeți, adica prin partea dreaptă. În această variantă de răspuns nu se specifică prin ce parte se ocolește centru intersecției, iar ocolirea centrului intersecţiei se facedoar prin dreapta acestuia, în sensul arătat de săgețile de pe indicatorul \"Intersecție cu sens giratoriu\", cu excepția celor care circulă pe prima stradă la dreapta,doar aceștiase vor angaja cât mai mult de marginea din dreapta a intersecției. Prioritatea de dreapta se acordă în intersecțiile cucirculație nedirijată, în cazul de față intersecția este una dirijată în care circulația se desfășoară în sens giratoriu și prioritate vor avea cei care circulă deja în interiorul intersecției, față de cei care doresc să pătrundă în intersecție.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0829.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0829.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 829; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă indicatorul circular albastru cu săgeți albe ce formează un cerc, care indică 'Sens giratoriu'. Acest semn obligă șoferii să circule în sensul indicat (anti-orar) în intersecțiile prevăzute cu sens giratoriu.","needsImageReview":true,"source":"RoDrive · ID 828 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatii-revin-conducatorilor-la-intalnirea-indicatorului","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"828","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_854.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0830","batch":"17","category":"Categoria B","question":"Ce semnificație are indicatorul alăturat?","answers":["Antenă obligatorie","Unde radar","Vânt lateral"],"correctIndices":[2],"correct":2,"explanation":"Indicatorul de avertizare din imagine semnifică \"Vânt lateral\". Acest indicator este amplasat în locurile unde există frecvent curenți puternici de aer care pot afecta circulația rutieră. Conducătorii auto trebuie să fie atenți la trecerea pe langa un autovehicul cu gabarit mare deoarece se poate forma fenomenul de absorbție sau acestea se pot dezechilibra mult mai ușor în prezența vânturilor laterale, din cauza gabaritului și a formei acestora.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0830.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0830.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 830; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Indicatorul triunghiular cu margine roșie și simbolul unui steag avertizează șoferii asupra pericolului reprezentat de vânt lateral puternic.","needsImageReview":true,"source":"RoDrive · ID 829 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-semnificatie-are-indicatorul-alaturat","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"829","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_855.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0831","batch":"17","category":"Categoria B","question":"Motociclistul depășește corect autocamionul?","answers":["Da, procedează corect","Nu, deoarece din sens opus circulă alt vehicul","Nu, deoarece indicatorul din imagine interzice acest lucru"],"correctIndices":[0],"correct":0,"explanation":"Motociclistul execută corect manevra de depășire a autocamionului deoarece semnalizează manevra, nu trece peste axul drumului, deci nu îl incomodează în niciun fel pe conducătorul autoturismului roșu, iar indicatorul “Depășirea autovehiculelor, cu excepția motocicletelor fără ataș, interzisă” nu se adresează conducătorilor de motociclete fără ataș. Prin urmare motociclistul procedează regulamentar. Dacă se trecea peste axul drumului, situația se schimba, iar conducătorul motocicletei proceda neregulamentar, deoarece atunci când prin manevra de depășire se trece peste axa care separa sensurile de circulație, conducătorii de vehicule trebuie să se asigure că din sens opus nu se apropie un vehicul.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0831.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0831.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 831; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o situație de depășire pe un drum cu câte o bandă pentru fiecare sens de mers. Indicatorul circular cu margini roșii și o mașină roșie și una neagră în interior interzice depășirea vehiculelor, cu excepția motocicletelor fără ataș. Motociclistul vrea să depășească autocamionul. Motocicleta este fără ataș și pentru a depăși, nu trece peste axul drumului. Camionul albastru se deplasează corect pe direcția sa. Un autoturism roșu se află pe sensul opus, care nu este deranjat de motociclist.","needsImageReview":true,"source":"RoDrive · ID 830 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/motociclistul-depaseste-corect-autocamionul","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"830","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_856.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0832","batch":"17","category":"Categoria B","question":"Care dintre cele două vehicule va intra primul în intersecție?","answers":["Motocicleta, deoarece se deplasează mai repede","Motocicleta, deoarece se deplasează pe direcția înainte","Autoturismul, deoarece se deplasează pe drumul prioritar"],"correctIndices":[2],"correct":2,"explanation":"Intersecția este dirijată cu indicatoare de reglementare de prioritate, sub fiecare indicator se găsește instalat câte un panou adițional care ne indică direcția drumului cu prioritate. Motocicleta vine de pe drumul fără prioritate, întâlnind indicatorul “Cedează trecerea” și trebuie să îi acorde prioritate autoturismului. Autoturismul circulă pe drumul cu prioritate, întâlnind indicatorul “Drum cu prioritate” și are prioritate de trecere. Prin urmare, dintre cele două vehicule, autoturismul va trece primul prin această intersecție iar motocicleta va trece a doua.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0832.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0832.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 832; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție semnalizată cu indicatorul romboidal cu fundal galben și margini albe 'Drum cu prioritate', însoțit de panou adițional ce îngroașă drumul de jos care continuă la stânga. Autoturismul albastru vine de jos și virează la stânga, aflându-se pe drumul evidențiat. Motociclistul vine din dreapta și vrea să meargă înainte, având indicatorul triunghiular cu margini roșii 'Cedează trecerea', cu panoul adițional care evidențiază același drum ca și celălalt indicator.","needsImageReview":true,"source":"RoDrive · ID 831 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-dintre-cele-doua-vehicule-va-intra-primul-in-intersectie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"831","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_857.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0833","batch":"17","category":"Categoria B","question":"Ce regulă de prioritate se aplică într-o intersecție nedirijată din afara localității?","answers":["Prioritatea vehiculului cu regim superior de viteză","Prioritatea drumului principal","Prioritatea de dreapta"],"correctIndices":[2],"correct":2,"explanation":"La intersecția nedirijată a două drumuride aceeași categorie, ca de exemplu o intersecție de două drumuri comunale sau două străzi dintr-un oraș, se va aplica regula priorității de dreapta, astfel vehiculul care vine din partea dreaptă are prioritate. Trebuie să reținem că regula priorității de dreapta se aplică doar in intersecțiile nedirijate de drumuride aceeași categorie. Dacă intersecția nedirijată este de drumuri de categorii diferite, ca de exemplu un drum județean și un drum comunal, prioritatea de trecere se va acorda în felul următor:","imageUrl":"/nivel-1/quiz-images/rodrive-all/0833.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0833.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 833; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 832 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-regula-de-prioritate-se-aplica-intr-o-intersectie-nedirijata-din-afara-localitatii","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"832","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0834","batch":"17","category":"Categoria B","question":"Când se restituie permisul de conducere reținut de către poliție în vederea suspendării exercitării dreptului de a conduce?","answers":["La hotărârea agentului de circulație","La expirarea termenului de suspendare, dacă a fost promovat testul de verificare a cunoștințelor, în situațiile prevăzute de lege","Atunci când procesul verbal de contravenție a fost anulat printr-o hotărâre judecătorească definitivă"],"correctIndices":[1,2],"correct":1,"explanation":"Permisul de conducere reținut de poliția rutieră în vederea suspendării exercitării dreptului de a conduce NU se poate restituii la hotărârea agentului de circulație, acesta trebuie să aibă un temei legal pentru a o face, însă legea nu prevede acest lucru. Pentru anumite contravenții săvârșite de către de către conducătorul de autovehicul, tractor agricol sau forestier ori tramvai se aplică suspendarea exercitării dreptului de a conduce șieste obligatoriepromovarea testului (examenului) de cunoaștere a regulilor de circulație (13 întrebări corecte din 15). De exemplu, pentru nerespectarea regulilor privind prioritatea de trecere, dacă prin aceasta s-a produs un accident de circulație din care au rezultat numai avarierea unui vehicul sau alte pagube materiale, se aplică amenda contravențională prevăzută în clasa a IV-a de sancțiuni, suspendarea dreptului de a conduce pentru o perioada de 90 de zile șieste obligatoriepromovarea testului (examenului) de cunoaștere a regulilor de circulație (chestionarul 13 întrebări corecte din 15, ce se găsește aici pe Școala Rutieră la categoria „Redobândire permis”). În cazul acestei contravenții permisul de conducere se restituie după expirarea perioadei de suspendare și promovarea testului de cunoaștere a regulilor de circulație. Dacă nu se promovează testul de cunoaștere a regulilor de circulație sau în caz de neprezentare pentru susținerea acestuia, perioada de suspendarese majorează cu încă 30 de zile, astfel permisul de conducere se restituie mai târziu cu 30 de zile față de expirarea perioadei de suspendare, perioada de suspendare se","imageUrl":"/nivel-1/quiz-images/rodrive-all/0834.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0834.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 834; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 833 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cand-se-restituie-permisul-de-conducere-retinut-de-catre-politie-in-vederea-suspendarii-exercitarii-dreptului-de-a-conduce","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"833","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0835","batch":"17","category":"Categoria B","question":"Dacă vehiculul pe care îl conduceți rămâne imobilizat pe calea ferată, aveți următoarea obligație:","answers":["Să scoateți imediat pasagerii din vehicul și să eliberați platforma căii ferate sau, când nu este posibil, să semnalizați prezența vehiculului cu orice mijloc adecvat","Să anunțați poliția","Să porniți autovehiculul prin orice mijloace"],"correctIndices":[0],"correct":0,"explanation":"Dacă vehiculul pe care îl conduceți rămâne imobilizat pe calea ferată, aveți obligația să scoateți imediat pasagerii din vehicul și să eliberați platforma căii ferate sau, când nu este posibilă eliberarea platformei căii ferate, trebuie să semnalizați prezența vehiculului cu orice mijloc adecvat.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0835.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0835.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 835; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 834 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/daca-vehiculul-pe-care-il-conduceti-ramane-imobilizat-pe-calea-ferata-aveti-urmatoarea-obligatie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"834","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0836","batch":"17","category":"Categoria B","question":"Este interzisă oprirea voluntară:","answers":["Pe trecerile pentru pietoni sau la mai puțin de 25 m, înainte și după acestea","La o distanță mai mică de 100 m, înainte și după trecerea la nivel cu calea ferată","La o distanță mai mică de 50 m, înainte și după stațiile mijloacelor de transport public"],"correctIndices":[0],"correct":0,"explanation":"Se interzice oprirea voluntară a vehiculelor pe trecerile pentru pietoni și la mai puțin de 25 de metri înainte și după acestea. Oprirea este permisă la o distanță mai mică de 100 de metri înainte și după trecerea la nivel cu calea ferată, oprirea fiind interzisă pe trecerile la nivel cu calea ferată curentă și la o distanță mai mică de 50 metri înainte și după acestea. Oprirea este permisa la o distanță mai mică de 50 de metri înainte și după stațiile mijloacelor de transport public, oprirea fiind interzisă în stațiile mijloacelor de transport public de persoane, precum și la mai puțin de 25 metri înainte si după acestea.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0836.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0836.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 836; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 835 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/este-interzisa-oprirea-voluntara","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"835","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0837","batch":"17","category":"Categoria B","question":"Este permisă pătrunderea pe racordurile dintre cele două părți carosabile ale unei autostrăzi?","answers":["Nu","Da, pentru oprire în caz de urgență","Da, pentru întoarcere, în zona intersecțiilor"],"correctIndices":[0],"correct":0,"explanation":"Pe autostradă se interzice pătrunderea pe racordurile dintre cele două parți carosabile. Aceste racorduri vor fi folosite exclusiv pentru situațiile în care administratorul drumului consideră că este necesară devierea circulației în caz de urgențe sau când se execută lucrări de reparații.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0837.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0837.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 837; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 836 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/este-permisa-patrunderea-pe-racordurile-dintre-cele-doua-parti-carosabile-ale-unei-autostrazi","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"836","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0838","batch":"17","category":"Categoria B","question":"Ce tendință prezintă un autoturism cu tracțiune pe spate, dacă accelerați prea puternic în curbă?","answers":["Autoturismul urmează, fără deviere, cursa volanului","Autoturismul tinde să derapeze cu spatele spre exteriorul curbei","Roțile din față se învârtesc în gol"],"correctIndices":[1],"correct":1,"explanation":"Atunci când conduceți un autoturism cu tracțiune pe spate și accelerați prea puternic în curbă, autovehiculul are tendința de a derapa spre exteriorul curbei, acest fenomen se numeștesupravirare. De aceea, în curbe trebuie redusă preventiv viteza de deplasare iar accelerarea se va face progresiv, după ieșirea din curbă. Cele două tipuri de derapaje sunt: Subvirarea- este un fenomen ce apare cel mai frecvent în cazul autovehiculelor cu motorul și puntea motoare față. Datorită faptului că roțile punții față sunt atât directoare cât și motoare, are loc o suprasolicitare a acestora în timpul în care autovehiculul virează. Acest fenomen se amplifică pe măsură ce forța de tracțiune (sau, după caz, forța de frânare) crește excesiv în timpul virajului. Cu alte cuvinte, o accelerare puternică sau o frânare bruscă efectuată în timpul virajului va provoca subvirarea autovehiculului. Consecința acestui lucru este pierderea aderenței dintre anvelope și calea de rulare, respectiv înscrierea autovehiculului pe o traiectorie necontrolată (deraparea acestuia). Supravirarea- este un alt fenomen de natură a duce la pierderea controlului autovehiculului în viraj și constă într-o rotire a autovehiculului în jurul axei sale. Aceasta este o caracteristică specifică autovehiculelor cu roțile motoare pe puntea spate și apare ori de câte ori anvelopele își pierd aderența. Ca și în cazul subvirării, fenomenul are loc în momentul când conducătorul auto frânează puternic în timpul virajului și este puternic accentuat de o uzură excesivă a anvelopelor sau de o parte carosabilă alunecoasă. Pentru a înțel","imageUrl":"/nivel-1/quiz-images/rodrive-all/0838.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0838.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 838; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 837 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-tendinta-prezinta-un-autoturism-cu-tractiune-pe-spate-daca-accelerati-prea-puternic-in-curba","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"837","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0839","batch":"17","category":"Categoria B","question":"Ce obligații are conducătorul de vehicule când circulă pe un drum public?","answers":["Să circule numai dacă verificarea medicală lunară este efectuată","Să circule numai pe sectoarele de drum pe care îi este permis accesul și să respecte normele referitoare la masele totale maxime autorizate admise de autoritatea competentă","Să se informeze din timp, la administratorii de drum, în legătură cu eventualele limite maxime și minime de viteză"],"correctIndices":[1],"correct":1,"explanation":"Legislația rutieră nu prevede obligația de a efectua lunar verificări medicale. Conducătorul de autovehicul, tractor agricol sau forestier ori tramvai, atunci când circulă pe un drum public este obligat să circule numai pe sectoarele de drum pe care îi este permis accesul și să respecte normele referitoare la masele totale maxime autorizate admise de autoritatea competentă, precum și toate celelalte reguli de circulație. Administratorul drumului public are obligația de a instala indicatoare, marcaje sau alte dispozitive care să informeze despre limitele de viteză. Iar dvs. trebuie să respectați semnificația acestora, fără să fiți obligat să vă informați la administratorii de drum în legătură cu eventualele limite maxime și minime de viteză.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0839.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0839.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 839; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 838 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatii-are-conducatorul-de-vehicule-cand-circula-pe-un-drum-public","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"838","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0840","batch":"17","category":"Categoria B","question":"Ce îi este interzis conducătorului de vehicule pe timpul deplasării pe un drum public?","answers":["Să transporte în vehicul mai multe persoane decât numărul de locuri înscrise în certificatul de înmatriculare sau înregistrare","Să permită controlul stării tehnice a vehiculului, precum și al bunurilor transportate","Să deschidă ușile vehiculului atunci când este parcat"],"correctIndices":[0],"correct":0,"explanation":"Îi este interzis conducătorului de autovehicul ca pe timpul deplasării pe un drum public să transporte în autovehicul mai multe persoane decât numărul de locuri înscrise în certificatul de înmatriculare sau înregistrare. Nu îi este interzis ci este obligat să permită controlul stării tehnice a autovehiculului, precum și al bunurilor transportate. Deschiderea ușilor autovehiculului se interzice doar atunci când acesta se afla în mișcare. Atunci când este parcat îi este permis să deschidă ușile autovehiculului, însă acesta este obligat să se asigure că aceasta manevră nu prezintă pericol pentru ceilalți participanți la trafic.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0840.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0840.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 840; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 839 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-ii-este-interzis-conducatorului-de-vehicule-pe-timpul-deplasarii-pe-un-drum-public","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"839","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0841","batch":"17","category":"Categoria B","question":"Cum trebuie să conduceți, astfel încât să reduceți poluarea?","answers":["Porniți motorul acționând pedala de accelerație la un sfert din cursă și așteptați ca acesta să se încălzească, pentru a reduce ulterior consumul de carburant","Porniți motorul fără să acționați pedala de accelerație și demarați imediat","Apăsați până la capăt pedala de accelerație, porniți motorul și demarați cu o viteză cât mai mare"],"correctIndices":[1],"correct":1,"explanation":"Nu trebuie să porniți motorul acționând pedala de accelerație la un sfert din cursă, astfel amestecul aer + carburant devine mai bogat în carburant și va crește poluarea. Nu trebuie să așteptați ca motorul să se încălzească, veți crește semnificativ și inutil consumul de combustibil și poluarea, motorul se va încălzi pe parcursul călătoriei. Primii pași în conducerea ecologica constau în demarajul corect, pornind motorul fără să acționați pedala de accelerație și demarați fără să staționați așteptând încălzirea motorului. Dacă apăsați până la capăt pedala de accelerație, porniți motorul și demarați cu o viteză cât mai mare, veți crește semnificativ și inutil consumul de combustibil și poluarea.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0841.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0841.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 841; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 840 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-trebuie-sa-conduceti-astfel-incat-sa-reduceti-poluarea","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"840","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0842","batch":"17","category":"Categoria B","question":"Ce cauze determină poluarea mediului ambiant de către autovehicule?","answers":["Rularea cu viteză redusă, fără motiv","Arderea incompletă și defectuoasă a combustibilului","Defectarea filtrului de benzină sau motorină"],"correctIndices":[1],"correct":1,"explanation":"Rularea cu viteză redusă, cu sau fără motiv, nu determină poluarea mediului ambiant în orice situație, dar dacă se va circula cu turații mari la viteze mici va crește consumul și, implicit, poluarea. Arderea incompletă și defectuoasă a combustibilului va face ca gazele evacuate să conțină mai multe reziduuri și determină poluarea mediului ambiant de către autovehicule. Defectarea filtrului de benzină sau motorină, mai exact înfundarea acestuia, va face ca sistemul de alimentare să nu mai ducă combustibilul către motor, caz în care motorul nu va mai funcționa, dar nu va determina poluarea mediului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0842.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0842.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 842; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 841 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-cauze-determina-poluarea-mediului-ambiant-de-catre-autovehicule","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"841","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0843","batch":"17","category":"Categoria B","question":"Ce măsuri trebuie să luați în situația dată?","answers":["Să acordați prioritate pietonilor","Să claxonați, pentru a avertiza pietonii","Să circulați cu prudență, întrucât indicatorul presemnalizează o trecere pentru pietoni"],"correctIndices":[2],"correct":2,"explanation":"Acordarea de prioritate se va face la trecerea de pietoni care urmează peste 50-200 de metri și doar pietonilor care traversează drumul public, atunci când aceștia se află pe sensul de mers al vehiculului. Indicatorul din imagine “Presemnalizare trecere pentru pietoni” doar avertizează că urmează o trecere pentru pietoni, acestanuobligă la acordarea de prioritate. Legislația rutieră nu prevede, ca măsură, să claxonați, pentru a avertiza pietonii. Claxonarea se va folosi pentru a preveni un pericol imediat. Trebuie să ținem cont că semnalizarea sonoră, precum claxonarea, este permisă doar de la o distanță de cel puțin 25 de metri față de cei cărora li se adresează. În această situație întâlniți indicatorul “Presemnalizare trecere pentru pietoni”, acest indicator vă avertizează că urmează o trecere pentru pietoni și impune sporirea atenției. Acest indicator este urmat întotdeauna de indicatorul “Trecere pentru pietoni”. Prin urmare, în situația dată, trebuie să circulați cu prudență pentru a putea reduce viteza și eventual să opriți dacă este cazul.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0843.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0843.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 843; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea arată o trecere de pietoni, la 150 de metri distanță, semnalizată prin indicatorul triunghiular de avertizare a faptului că se apropie o trecere de pietoni.","needsImageReview":true,"source":"RoDrive · ID 842 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-masuri-trebuie-sa-luati-in-situatia-data","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"842","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_868.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0844","batch":"17","category":"Categoria B","question":"Indicatorul semnifică:","answers":["Circulația se desfășoară în ambele sensuri","Sfârșitul interzicerii de a depăși","Sfârșitul zonei cu viteză recomandată"],"correctIndices":[1],"correct":1,"explanation":"Indicatorul pe care l-ați întâlnit se numește “Sfârșitul interzicerii de a depăși”. Acest indicator anunță terminarea sectorului de drum pe care depășirea a fost interzisă prin indicatorul \"Depășirea autovehiculelor, cu excepția motocicletelor fără ataș, interzisă\" sau prin indicatorul \"Depășirea interzisă autovehiculelor destinate transportului de mărfuri\". După întâlnirea indicatorului \"Sfârșitul interzicerii de a depăși\" manevra de depășire vă este permisă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0844.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0844.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 844; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un drum ce conține indicatorul circular alb cu două vehicule negre tăiate de o linie neagră, ce semnifică sfârșitul interdicției de depășire.","needsImageReview":true,"source":"RoDrive · ID 843 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/indicatorul-semnifica","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"843","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_869.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0845","batch":"17","category":"Categoria B","question":"Ce semnificație are un astfel de marcaj rutier?","answers":["Marcaj pe o bandă de decelerare","Deviere temporară a circulației","Marcaj pentru spații interzise"],"correctIndices":[0],"correct":0,"explanation":"Acest marcaj rutier este un marcaj aplicat pe o bandă de decelerare. Banda de decelerare se folosește pentru executarea virajului la dreapta de pe un drum prioritar sau de pe o autostradă. La executarea virajului la dreapta, conducătorii de vehicule fiind obligați să circule cu o viteză care să nu depășească 30km/h în localități sau 50 km/h în afara acestora, fără a stânjeni circulația celorlalte vehicule.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0845.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0845.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 845; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un drum cu marcaje rutiere care indică apariția unei benzi de decelerare, de pe un drum principal sau autostradă.","needsImageReview":true,"source":"RoDrive · ID 844 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-semnificatie-are-un-astfel-de-marcaj-rutier","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"844","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_870.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0846","batch":"17","category":"Categoria B","question":"Viteza maximă autorizată pe autostrăzi pentru autovehiculele din categoriile A și B este de:","answers":["90 km/h","110 km/h","130 km/h"],"correctIndices":[2],"correct":2,"explanation":"Limita maximă de viteză pe drumurile din afara localităților este de130 km/h pe autostrăzi, 120 km/h pe drumurile expres, 100 km/h pe drumurile naționale europene (E) și 90 km/h pe celelalte categorii de drumuri. Aceste limite maxime de viteză sunt limitele maxime care se pot stabilii pe drumurile publice din România. Trebuie știut că,în funcție de categoria drumului pe care se circulă și de categoria autovehiculului condus, limitele maxime de viteză sunt diferite. Limitele maxime de viteză pentru autovehiculele din categoriile A și B pe drumurile din afara localităților coincid cu limitele maxime care se pot stabilii pe drumurile publice din România:130 km/h pe autostrăzi, 120 km/h pe drumurile expres, 100 km/h pe drumurile naționale europene (E) și 90 km/h pe celelalte categorii de drumuri.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0846.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0846.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 846; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea arată un sector de autostradă, cu un indicator verde care indică direcția către Constanța pe autostrada A2. Indicatorul afișează restricții precum interzicerea accesului pietonilor, bicicletelor și vehiculelor lente.","needsImageReview":true,"source":"RoDrive · ID 845 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/viteza-maxima-autorizata-pe-autostrazi-pentru-autovehiculele-din-categoriile-a-si-b-este-de","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"845","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_871.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0847","batch":"17","category":"Categoria B","question":"Care dintre autoturisme staționează greșit?","answers":["Autoturismul alb","Autoturismul roșu","Ambele autoturisme"],"correctIndices":[2],"correct":2,"explanation":"În situația dată cele două autoturisme staționează neregulamentar deoarece staționarea vehiculelor este interzisă pe trecerile pentru pietoni sau la mai puțin de 25 de metri înainte și după acestea.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0847.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0847.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 847; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o trecere de pietoni semnalizată prin indicatorul albastru 'Trecere pentru pietoni'. Autoturismul alb este staționat pe trecerea de pietoni, iar autoturismul roșu este staționat fix în fața trecerii.","needsImageReview":true,"source":"RoDrive · ID 846 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-dintre-autoturisme-stationeaza-gresit","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"846","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_872.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0848","batch":"17","category":"Categoria B","question":"Cum este corect să procedați dacă semafoarele funcționează cu lumina galbenă intermitentă?","answers":["Reduceți viteza și traversați intersecția","Reduceți viteza și cedați trecerea","Opriți și cedați trecerea"],"correctIndices":[0],"correct":0,"explanation":"Semnalul de culoare galben intermitent permite trecerea, conducătorul de vehicul fiind obligat să circule cu viteză redusă, să respecte semnificația semnalizării rutiere și a regulilor de circulație aplicabile în acel loc. În această situație trebuie să respectați semnificația indicatoarelor, iar indicatorul „Drum cu prioritate” vă permite trecerea. În situația dată veți reduce viteza și veți traversa intersecția deoarece aveți prioritate.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0848.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0848.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 848; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea arată o intersecție semnalizată cu indicatorul 'Drum cu prioritate' (romb galben) și un semafor. Semaforul strălucește galben intermitent.","needsImageReview":true,"source":"RoDrive · ID 847 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-este-corect-sa-procedati-daca-semafoarele-functioneaza-cu-lumina-galbena-intermitenta","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"847","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_873.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0849","batch":"17","category":"Categoria B","question":"Vă este permis să depășiți bicicliștii?","answers":["Da, dacă prin claxonare bicicliștii sunt determinați să se angajeze cât mai spre dreapta","Nu, pentru că din cauza circulației din sens opus nu se poate păstra o distanță laterală corespunzătoare","Bicicliștii pot fi depășiți fără restricții"],"correctIndices":[1],"correct":1,"explanation":"În primul rând, nu se permite determinarea celorlalți participanți la trafic să părăsească partea carosabilă sau să se retragă din calea dvs.. Acest comportament este considerat a fi unul agresiv și este interzisă adoptarea acestuia în timpul conducerii vehiculelor pe drumurile publice. În al doilea rând, claxonul poate fi folosit doar de la o distanță de cel puțin 25 de metri de cei cărora li se adresează iar în cazul de față sunteți prea aproape de acești bicicliști și nu vă este permis să îi claxonați. Pentru a asigura odistanță laterală de siguranță corespunzătoare, conducătorii de autovehicule (cu excepția autovehiculelor cu două roți), vor efectua manevra de depășire a bicicletelor sau a trotinetelor electrice respectând,pe lângă obligațiile privind manevra de depășire,și următoarele obligații,în funcție de viteza cu care aceștia se deplasează(art. 118 alin. 2 din Regulament): În concluzie, dacă te deplasezicu până la 50de km/h ești obligatmăcar să încalci marcajul, iar dacă te deplasezicu mai mult de 50 de km/hești obligatmăcar să treci cu jumătate din lățimea autovehiculului peste marcaj. Trebuie reținut că acestea de mai sus nu sunt doar recomandări, acestea sunt obligații, iar nerespectarea lor se sancționează conform legii. De reținut că în cazul în care un sector de drum are acest marcaj realizat culinie continuănu se mai poate efectua depășirea bicicletelor sau trotinetelor electrice, pentru căeste interzisă încălcarea sau trecerea peste acest marcaj cu linie continuă, iarpentru depășirea acestor vehicule este obligatorie încălcarea sau trecerea peste acest mar","imageUrl":"/nivel-1/quiz-images/rodrive-all/0849.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0849.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 849; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea arată un drum urban cu bicicliști care circulă pe partea dreaptă a carosabilului. Șoferul intenționează să depășească bicicliștii. Sensurile de mers sunt separate de marcajul transversal longitudinal discontinuu, care permite depășirea, dacă se poate încadra pe sens opus. Pe sensul opus de mers este trafic intens, ce nu îi permite să se încadreze pe sensul opus","needsImageReview":true,"source":"RoDrive · ID 848 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/va-este-permis-sa-depasiti-biciclistii","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"848","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_874.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0850","batch":"17","category":"Categoria B","question":"Este permisă depășirea în această situație?","answers":["Da, dar numai după oprirea autoturismului","Nu","Da, dar numai dacă vizibilitatea permite"],"correctIndices":[1],"correct":1,"explanation":"În această situație circulați pe un drum ce are o singură bandă pe sensul dvs. de mers, în apropierea unei curbe, și intenționat să depășiți autovehiculul roșu din față care se deplasează cu viteză redusă. Legislația rutieră interzice efectuarea manevrei de depășire a vehiculelor în anumite locuri și situații, printre care și în curbe, indiferent dacă se încalcă sau nu marcajul longitudinal cu linie continuă și indiferent dacă se intră sau nu pe sensul opus. În această situație întâlniți și marcajul longitudinal format dintr-o linie continuă iar depășirea vehiculelor este interzisă când pentru efectuarea manevrei se încalcă marcajul continuu, simplu sau dublu, care desparte sensurile de mers, iar autovehiculul circulă, chiar și parțial, pe sensul opus. Prin urmare, în această situație nu vă este permisă depășirea autoturismului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0850.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0850.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 850; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un drum cu curbe periculoase, semnalizat prin indicatorul circular cu margini roșii și pe care scrie cu negru 50 de limitare a vitezei la 50 km/h și prin indicatoarele pătrate cu o săgeată roșie spre stânga, ce indică prezența unei curbe periculoase. De asemenea, sunt vizibile parapete de protecție și marcaje rutiere clare. Sensurile de mers sunt separate prin marcajul longitudinal cu linie continuă. Șoferul are în față o mașină pe care dorește să o depășească.","needsImageReview":true,"source":"RoDrive · ID 849 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/este-permisa-depasirea-in-aceasta-situatie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"849","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_875.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"}]);})();
